-- Planilha 'Artigos Publicados - Geral' enviada pela coordenação (10/11/2026). Pode ser executado mais de uma vez.
begin;
update public.conquistas c set url='https://doi.org/10.5753/encompif.2023.230781' where (c.tipo='ARTIGO' and c.titulo ilike 'Acesso a formação em Inteligência Artificial%' and c.veiculo ilike '%ENCompIF%') and c.url='';
update public.conquistas c set url='https://www.sba.org.br/cba2024/papers/paper_7731.pdf' where (c.tipo='ARTIGO' and c.titulo ilike 'Construção de um submarino robô de baixo custo%') and c.url='';
update public.conquistas c set url='https://www.researchgate.net/publication/385173842_Desenvolvimento_de_um_veiculo_subaquatico_remotamente_operado_de_baixo_custo_para_fins_educacionais' where (c.tipo='ARTIGO' and c.titulo ilike 'Desenvolvimento de um veículo subaquático operado remotamente, de baixo custo%') and c.url='';
update public.conquistas c set url='https://www.researchgate.net/publication/391275672_Low-Cost_Optical_Communication_System_for_Short-Range_Underwater_Applications' where (c.tipo='ARTIGO' and c.titulo ilike 'Low-Cost Optical Communication System%') and c.url='';
commit;
select (select count(*) from public.pessoas) pessoas, (select count(*) from public.conquistas) conquistas, (select count(*) from public.conquistas where tipo in ('ARTIGO','TCC','EVENTO')) publicacoes, (select count(*) from public.conquistas where tipo in ('ARTIGO','TCC','EVENTO') and url<>'') com_link;
