insert into public.conquistas (tipo,titulo,ano,veiculo,autores,descricao,url,projeto_id,publicado) select 'EVENTO','Desenvolvimento de um robô de duas rodas de autoequilíbrio utilizando o princípio de um pêndulo invertido',2024,'Mostra Nacional de Robótica (MNR 2024)','','Trabalho publicado nos anais.','https://us.docworkspace.com/d/sIKrW3PnjAY-x2cEG',(select id from public.projetos where slug='robo-equilibrista'),true where not exists (select 1 from public.conquistas c where lower(c.titulo)=lower('Desenvolvimento de um robô de duas rodas de autoequilíbrio utilizando o princípio de um pêndulo invertido') and c.tipo='EVENTO' and c.veiculo='Mostra Nacional de Robótica (MNR 2024)');
insert into public.conquista_pessoas (conquista_id,pessoa_id) select c.id, pe.id from public.conquistas c, public.pessoas pe where (lower(c.titulo)=lower('Desenvolvimento de um robô de duas rodas de autoequilíbrio utilizando o princípio de um pêndulo invertido') and c.tipo='EVENTO' and c.veiculo='Mostra Nacional de Robótica (MNR 2024)') and pe.slug='luiz-eduardo-andrade-de-oliveira' on conflict do nothing;
insert into public.conquista_pessoas (conquista_id,pessoa_id) select c.id, pe.id from public.conquistas c, public.pessoas pe where c.autores ilike '%Raíra Zahara%' and pe.slug='raira-zahara-alves-de-oliveira' on conflict do nothing;
insert into public.conquista_pessoas (conquista_id,pessoa_id) select c.id, pe.id from public.conquistas c, public.pessoas pe where c.autores ilike '%João Vieira Neto%' and pe.slug='joao-vieira-neto' on conflict do nothing;
